(66, 3, 'Polishing Spray - Axegear Sealant Guard Mengilapkan dan Melindungi Cat Kendaraan | Cairan Pengkilap Body Motor Axegear', 'polishing-spray-axegear-sealant-guard-mengilapkan-dan-melindungi-cat-kendaraan-cairan-pengkilap-body-motor-axegear', 'AXE-NEW-MC-SG-0584', 'Axegear', NULL, NULL, 40000.00, 35000.00, 'Polishing Spray - Axegear Sealant Guard', '<p>Polishing Spray - Axegear Sealant Guard</p><p></p><p>Detail :</p><p>- Size 100 ml</p><p>- Aroma Jeruk/Orange</p><p>- Botol Spray halus dan merata</p><p></p><p>Kegunaan :</p><p>- Semi Coating mengilapkan, melindungi cat kendaraan.</p><p>- Memberikan efek Daun Talas untuk mencegah kotoran menempel</p><p>- Menyamarkan baret halus pada kendaraan</p><p>- Dikemas dengan plastik Seal dan Dus box</p><p></p><p>Pengiriman Senin-Sabtu</p><p>Last order jam 15:00 WIB, Sabtu 11:00 WIB</p><p></p><p>Garansi Produk (gratis produk pengganti apabila produk yang diterima rusak karena kesalahan kami)</p><p>Garansi Original (garansi uang kembali 200% jika barang palsu)</p><p>Garansi Kepuasan (admin kami siap melayani jika ada kendala)</p><p></p><p>WAJIB MENYERTAKAN VIDEO UNBOXING UNTUK KLAIM GARANSI</p>', 'published', 250, 10, 5, 10, 0, 0, 0, NULL, '2026-09-10 09:38:24', '2026-09-14 06:20:21');

